"""Builds index.html (self-contained) from results.json + figures/ + code chunks of analysis.py."""
import json, base64, html, re, math
R = json.load(open("results.json")); SRC = open("analysis.py").read()
CODE = {m.group(1): m.group(2).strip() for m in re.finditer(r"#%% (\w+)[^\n]*\n(.*?)(?=\n#%% |\Z)", SRC, re.S)}
esc = html.escape
f3 = lambda x, d=3: f"{x:,.{d}f}"
def pv(p): return "&lt; 0.001" if p < 1e-3 else f"{p:.3f}"
def fig(name, cap):
    b = base64.b64encode(open(f"figures/{name}.png", "rb").read()).decode()
    return f'<figure><img loading="lazy" src="data:image/png;base64,{b}" alt="{esc(cap)}"><figcaption>{cap}</figcaption></figure>'
def tbl(head, rows):
    return '<div class="tw"><table><thead><tr>' + "".join(f"<th>{h}</th>" for h in head) + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</tbody></table></div>"
def bub(items): return '<div class="bubs">' + "".join(f'<div class="bub"><b>{v}</b><span>{k}</span></div>' for k, v in items) + "</div>"
def code(key): return f'<details class="code"><summary>Show implementation (analysis.py › {key})</summary><pre><code>{esc(CODE[key])}</code></pre></details>'
def task(title, obj, meth, impl, res, interp, extra=""):
    return f'''<article class="task"><h3>{title}</h3><div class="grid2"><div class="pill"><h4>Objective</h4><p>{obj}</p></div><div class="pill"><h4>Methodology</h4><p>{meth}</p></div></div>
<h4>Implementation</h4>{impl}<h4>Results</h4>{res}<div class="interp"><h4>Interpretation</h4>{interp}</div>{extra}</article>'''
SQ = '<svg class="sq" viewBox="0 0 120 50" aria-hidden="true"><path d="M5 40 C20 5 30 5 40 25 S60 45 75 15 S100 5 115 30" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round"/></svg>'
def sec(id_, color, title, sub, los, body, num):
    return f'<section id="{id_}" class="slide c-{color}"><div class="sh">{SQ}<span class="mod">{num}</span><h2>{title}</h2><p class="sub">{sub}</p><div class="los">{"".join(f"<span>{l}</span>" for l in los)}</div></div>{body}</section>'

m1, m2, m3, m4, m5, m6 = (R[k] for k in ["m1", "m2", "m3", "m4", "m5", "m6"])
mean = lambda a: sum(a) / len(a)
kf = m1["kfold"]

# ---------------- Module 1
d1 = task("Task 1.1 — Data profiling and preparation",
          "Understand volume, dimensionality and quality of the wildlife-trafficking listing data before any modelling (Contents 1.1–1.3).",
          "Load all CSVs, count rows/columns/types, check missing values and duplicates, clean titles (strip the “| eBay” suffix), engineer numeric features, and de-duplicate titles for the ML copy so identical listings cannot leak across folds.",
          code("M1"),
          bub([("shark listings (11 raw columns)", f"{m1['rows']:,}"), ("leather listings", f"{m1['leather_rows']:,}"), ("positive (shark-product) rate", f"{m1['pos_rate']*100:.1f}%"), ("distinct sellers", f"{m1['sellers']:,}")]) +
          tbl(["Check", "Result"], [["Shark file in memory / leather file in memory", f"{m1['memory_mb']:.0f} MB / {m1['leather_memory_mb']:.0f} MB"], ["Missing values (shark)", f"image: {m1['missing']['image']}, location: {m1['missing']['location']}"], ["Duplicate URLs / duplicate titles", f"{m1['dup_urls']} / {m1['dup_titles']} (conflicting labels among duplicates: {m1['conflicting_dup_titles']})"], ["Retrieval window", f"{m1['t_min'][:10]} → {m1['t_max'][:10]}"], ["Modelling copy after title de-duplication", f"{m1['ml_rows']:,} rows, {m1['ml_pos']} positive"]]),
          "<p>The data is <b>high-volume and mixed-type</b>: free text (titles), numeric (price), categorical (country, seller) and timestamps. The classes are strongly imbalanced (about 1 in 18 listings is positive), which dictates metric choice (F1 and average precision rather than accuracy) and motivates the SMOTE comparison in Module 5. Very few duplicates exist, so leakage risk is small but was removed anyway.</p>")
d1b = task("Task 1.2 — Model building with k-fold cross-validation and bootstrapping",
           "Build a baseline text classifier for “is this listing a shark product?” and estimate how well it generalises (Content 1.4, LO 1.4).",
           "TF-IDF (1–2-grams) + logistic regression on the cleaned title. Stratified 5-fold CV for F1, precision, recall, average precision. A bootstrap (B = 100) refits on resampled training rows and scores on the out-of-bag rows to get a percentile interval.",
           "<p class='note'>Implemented in the M1 chunk shown in Task 1.1.</p>",
           bub([("CV F1 (mean)", f3(mean(kf['f1']))), ("CV precision", f3(mean(kf['precision']))), ("CV recall", f3(mean(kf['recall']))), ("CV avg. precision", f3(mean(kf['average_precision'])))]) +
           fig("m1_validation", "Left: F1 of each CV fold. Right: distribution of out-of-bag F1 across 100 bootstrap refits.") +
           f"<p>Bootstrap out-of-bag F1: mean {f3(m1['boot_f1']['mean'])}, 95% percentile interval [{f3(m1['boot_f1']['lo'])}, {f3(m1['boot_f1']['hi'])}].</p>",
           f"<p>Performance is stable across folds (F1 {min(kf['f1']):.2f}–{max(kf['f1']):.2f}) and the bootstrap interval is consistent with it. The model is <b>highly precise but misses many positives</b> (precision {mean(kf['precision']):.2f} vs recall {mean(kf['recall']):.2f}). Accuracy would have looked excellent (about 94.5%) simply by predicting “negative”, which is why it is not used. <b>Not performed:</b> leave-one-out CV (14.5k refits of a text pipeline was judged impractical and k-fold is the standard substitute at this size).</p>")
s1 = sec("m1", "plum", "Introduction to Data Science", "Data, process, preparation, validation", ["LO 1.1", "LO 1.2", "LO 1.3", "LO 1.4"], d1 + d1b +
         '<div class="pill wide"><h4>Data science vs. data analytics (Content 1.5–1.6)</h4><p>Here, <b>analytics</b> is the descriptive/inferential work of Modules 2–3 (what does the market look like, are groups different?), while <b>data science</b> adds predictive and automated components: classifiers, regression, anomaly detectors and forecasts (Modules 4–6) evaluated with held-out data. The application domain is wildlife-trade triage: scanning large marketplace crawls for illegal animal products.</p></div>', "01")

# ---------------- Module 2
def drow(c, lab): d = m2[c]; return [lab, f"{d['mean']:.2f}", f"{d['median']:.2f}", f"{d['mode']:.2f}", f"{d['std']:.2f}", f"{d['iqr']:.2f}", f"{d['pearson_skew']:.2f}", f"{d['bowley']:.2f}", f"{d['moment_skew']:.2f}", f"{d['excess_kurtosis']:.1f}"]
t21 = task("Task 2.1 — Univariate exploration",
           "Summarise price and title characteristics: central tendency, spread, symmetry, skewness and kurtosis (Contents 2.1–2.3, LO 2.1–2.3).",
           "Mean/median/mode, SD, IQR, CV; Karl Pearson’s coefficient 3(mean − median)/SD; Bowley’s quartile coefficient; moment skewness and excess kurtosis. Price is also analysed on a log scale.",
           code("M2"),
           tbl(["Variable", "Mean", "Median", "Mode", "SD", "IQR", "Pearson skew", "Bowley", "Moment skew", "Excess kurt."], [drow("price", "Price (USD)"), drow("log_price", "ln(price)"), drow("title_len", "Title length"), drow("n_words", "Words in title")]) +
           fig("m2_hist", "Histograms: raw price (clipped at the 99th percentile), ln(price) with KDE, and title length."),
           f"<p>Raw price is extremely right-skewed: mean ${m2['price']['mean']:.0f} vs median ${m2['price']['median']:.0f}, moment skewness {m2['price']['moment_skew']:.1f}, excess kurtosis {m2['price']['excess_kurtosis']:,.0f}. Note that Karl Pearson’s coefficient is only {m2['price']['pearson_skew']:.2f} here because it uses the median and divides by an SD inflated by the extreme tail, so it badly understates this skew; Bowley’s coefficient ({m2['price']['bowley']:.2f}) and the moment skewness agree on positive skew. After the log transform, skew drops to {m2['log_price']['moment_skew']:.2f} with modest kurtosis ({m2['log_price']['excess_kurtosis']:.1f}). Title length is mildly left-skewed, capped by eBay’s 80-character limit.</p>")
t22 = task("Task 2.2 — Multivariate exploration and visualisation",
           "Examine relationships between price, text features and the shark-product label (Contents 2.4–2.5, LO 2.4–2.6).",
           "Pearson and Spearman correlation, scatter plot, scatter matrix, correlation heatmap, violin / box / boxen plots by label, and a bubble chart by seller country.",
           "<p class='note'>Code for these plots is in the same M2 chunk shown above.</p>",
           fig("m2_violin_box", "Violin, box and boxen plots comparing positive (1) and negative (0) listings.") + fig("m2_scatter", "Scatter plot of title length vs ln(price), 4,000-row random sample.") + fig("m2_pairplot", "Scatter matrix (pair plot) on a 1,500-row sample.") + fig("m2_heatmap", "Pearson correlation heatmap.") + fig("m2_bubble", "Bubble chart for the 8 largest seller countries."),
           f"<p>Title length and ln(price) are essentially uncorrelated (Pearson r = {m2['title_len_vs_logprice']['pearson']:.3f}, Spearman ρ = {m2['title_len_vs_logprice']['spearman']:.3f}; statistically detectable only because n is large). Positive listings are priced higher: median ${m2['by_label'][1]['median_price']:.2f} vs ${m2['by_label'][0]['median_price']:.2f}. The bubble chart shows the US dominating volume (≈{12659/14533*100:.0f}% of listings) and a higher positive share there than in several other countries (formally tested in Module 3).</p>")
s2 = sec("m2", "teal", "Data Exploration: Descriptive Statistics", "Centre, spread, shape and visual analytics", [f"LO 2.{i}" for i in range(1, 7)], t21 + t22, "02")

# ---------------- Module 3
z, tt, an = m3["ztest"], m3["ttest"], m3["anova"]
t31 = task("Task 3.1 — Distributions: Normal, CLT and Poisson", "Check which standard distributions describe the data (LO 3.1).",
           "Shapiro–Wilk / D’Agostino tests and Q-Q plot for ln(price); a simulation of the Central Limit Theorem on the raw price (3,000 resamples at n = 5, 30, 300); a Poisson goodness-of-fit (dispersion) check on hourly listing-retrieval counts.",
           code("M3"),
           fig("m3_normal", "Q-Q plot and fitted normal curve for ln(price).") + fig("m3_clt", "CLT demonstration: sampling distribution of the mean price.") +
           tbl(["Check", "Result"], [["Shapiro–Wilk (n = 5000 sample)", f"W = {m3['shapiro_W']:.3f}, p {pv(m3['shapiro_p'])}"], ["Skewness of sample means (population skew = %.1f)" % m3["pop_skew"], " / ".join(f"n={k}: {v['skew']:.2f}" for k, v in m3["clt"].items())], ["Poisson fit, hourly counts (%d h)" % m3["poisson"]["n_hours"], f"mean {m3['poisson']['lam']:.1f}, variance {m3['poisson']['var']:.0f}, dispersion {m3['poisson']['dispersion']:.1f}, p {pv(m3['poisson']['chi2_p'])}"]]),
           "<p>ln(price) is <b>not exactly normal</b> (formally rejected; it is mildly right-skewed with slightly heavy tails) but is far closer to normal than raw price, so it is used for parametric methods. The CLT is visible: sample-mean skew shrinks from 12.4 at n = 5 to 1.8 at n = 300, yet is still not normal at n = 300 because the raw price tail is so heavy. <b>Hourly counts are not Poisson</b>: the variance is about 33 times the mean (over-dispersion), consistent with crawler batching rather than independent arrivals.</p>")
t32 = task("Task 3.2 — Confidence intervals and hypothesis tests", "Quantify uncertainty and test group differences (LO 3.2–3.4).",
           "95% t-intervals (price, ln price), Wilson interval for the positive rate; two-proportion Z-test (US vs non-US positive share); Welch t-test on ln(price) for positive vs negative listings with Cohen’s d; one-way ANOVA of ln(price) across the five largest seller countries, with Levene (equal variance) and Kruskal–Wallis (non-parametric) checks.",
           "<p class='note'>Implemented in the M3 chunk above.</p>",
           tbl(["Quantity", "Estimate", "95% CI"], [["Mean price (USD)", f"{m3['ci_price']['mean']:.2f}", f"[{m3['ci_price']['lo']:.2f}, {m3['ci_price']['hi']:.2f}]"], ["Geometric-mean price (USD)", f"{m3['ci_geo_price']['mean']:.2f}", f"[{m3['ci_geo_price']['lo']:.2f}, {m3['ci_geo_price']['hi']:.2f}]"], ["Positive rate", f"{m3['ci_pos_rate']['p']*100:.2f}%", f"[{m3['ci_pos_rate']['lo']*100:.2f}%, {m3['ci_pos_rate']['hi']*100:.2f}%]"]]) +
           tbl(["Test", "Statistic", "p-value", "Effect"], [["Two-proportion Z (US vs non-US positive share)", f"z = {z['z']:.2f}", pv(z["p"]), f"{z['p_us']*100:.1f}% vs {z['p_nonus']*100:.1f}%"], ["Welch t (ln price, positive vs negative)", f"t = {tt['t']:.2f} (df {tt['df']:.0f})", pv(tt["p"]), f"means {tt['mean1']:.2f} vs {tt['mean0']:.2f}; Cohen’s d = {tt['cohen_d']:.2f}"], [f"One-way ANOVA ({', '.join(an['countries'])})", f"F = {an['F']:.1f}", pv(an["p"]), f"η² = {an['eta2']:.3f}"], ["Levene (equal variances)", "–", pv(an["levene_p"]), "variances differ"], ["Kruskal–Wallis", f"H = {an['kruskal_H']:.0f}", pv(an["kruskal_p"]), "agrees with ANOVA"]]) +
           fig("m3_anova", "ANOVA groups: ln(price) by seller country."),
           f"<p>The mean price CI is wide ([{m3['ci_price']['lo']:.0f}, {m3['ci_price']['hi']:.0f}] USD) because of the heavy tail, whereas the geometric mean (≈ ${m3['ci_geo_price']['mean']:.0f}) is tightly estimated. Positive listings are priced significantly higher (medium effect, d = {tt['cohen_d']:.2f}), and US listings are more likely to be positive than non-US ones. Country differences in price are statistically significant but <b>small in size</b> (η² ≈ {an['eta2']*100:.0f}% of variance), and since Levene rejects equal variances the ANOVA is backed by the Kruskal–Wallis result rather than relied on alone; Japan stands out as the high-priced group (mean ln price {an['means']['Japan']:.2f}).</p>")
t33 = task("Task 3.3 — Type-I and Type-II errors", "Show the meaning of α and power empirically (LO 3.4).",
           "Permute the labels 1,000 times and count how often the Welch t-test falsely rejects at α = 0.05 (empirical Type-I rate). Compute power for the observed effect and the minimum detectable effect size at 80% power with the actual group sizes.", "<p class='note'>Implemented in the M3 chunk above.</p>",
           bub([("empirical Type-I rate (target 0.05)", f"{m3['type1_rate']:.3f}"), ("power at observed d", f"{m3['power_observed']:.2f}"), ("min. detectable d at 80% power", f"{m3['mde_d_80']:.2f}")]),
           f"<p>The test is well calibrated: under shuffled labels it rejects {m3['type1_rate']*100:.1f}% of the time, close to the nominal 5%. With 801 vs 13,732 listings the test can detect effects as small as d ≈ {m3['mde_d_80']:.2f}, so the Type-II risk for the observed medium effect is negligible. The flip side is that with this much data almost <i>any</i> difference becomes “significant”, so effect sizes (d, η²) matter more than p-values.</p>")
s3 = sec("m3", "pink", "Data Exploration: Inferential Statistics", "Distributions, intervals, tests and error types", [f"LO 3.{i}" for i in range(1, 5)], t31 + t32 + t33, "03")

# ---------------- Module 4
mt = m4["table"]; best = next(r for r in mt if r["model"] == m4["best"]); coefs = m4["coef"]
cname = {"Intercept": "Intercept", "title_len": "Title length (chars)", "n_words": "Words in title", "upper_ratio": "Share of upper-case letters", "has_digit": "Title contains a digit", "label": "Shark-product label = 1", "is_us": "US seller", "log_desc": "ln(1 + description length)", "kw_jaw": "Title says “jaw”", "kw_tooth": "Title says “tooth/teeth”", "kw_fossil": "Title says “fossil/megalodon”"}
cd = {c["term"]: c for c in coefs}
t41 = task("Task 4.1 — Simple to multiple regression for ln(price)", "Build, compare and select regression models for price (LO 4.1–4.6).",
           "Four nested OLS models (statsmodels) on an 80% training split, evaluated on a 20% test split: A) title length only; B) + text-shape features; C) + label, US seller, description length; D) + keyword indicators. Fit measures: R², adjusted R², AIC/BIC, overall F-test, nested F-tests, t-tests per coefficient, and test-set MAE and MAPE on the USD scale (back-transformed with Duan’s smearing factor).",
           code("M4"),
           tbl(["Model", "k", "R² (train)", "Adj. R²", "AIC", "F (p)", "Test R² (ln)", "Test MAE ($)", "Test MAPE (%)"], [[r["model"], r["k"], f3(r["r2"]), f3(r["adj_r2"]), f"{r['aic']:,.0f}", f"{r['F']:.0f} ({pv(r['F_p'])})", f3(r["test_r2_log"]), f"{r['test_mae_usd']:.1f}", f"{r['test_mape_pct']:.0f}"] for r in mt]) +
           f"<p>Constant-median baseline on the same test set: MAE ${m4['baseline_mae_usd']:.1f}, MAPE {m4['baseline_mape_pct']:.0f}%.</p>" +
           tbl(["Term (final model " + m4["best"][0] + ")", "Coef.", "Std. err.", "t", "p", "95% CI", "Effect on price"], [[cname[c["term"]], f3(c["coef"]), f3(c["se"]), f"{c['t']:.2f}", pv(c["p"]), f"[{c['lo']:.3f}, {c['hi']:.3f}]", "–" if c["term"] == "Intercept" else f"{(math.exp(c['coef'])-1)*100:+.0f}% per unit"] for c in coefs]) +
           tbl(["Nested comparison", "F", "p"], [[k, f"{v['F']:.1f}", pv(v["p"])] for k, v in m4["nested_F"].items()]) +
           fig("m4_compare", "Adjusted R² (train) and test R² for models A–D.") + fig("m4_residuals", "Residual diagnostics and test-set actual vs predicted for the selected model."),
           f"<p><b>Meaning of the parameters:</b> the intercept ({cd['Intercept']['coef']:.2f}) is the predicted ln-price of a title with all predictors at zero; each slope is the change in ln-price per unit holding the others fixed (partial coefficient), so exp(β)−1 is the % price change. Holding other terms constant, a positive (shark-product) listing is about {(math.exp(cd['label']['coef'])-1)*100:.0f}% pricier, a title containing a digit about {(math.exp(cd['has_digit']['coef'])-1)*100:.0f}% pricier, and a title with “tooth/teeth” about {(math.exp(cd['kw_tooth']['coef'])-1)*100:.0f}% pricier; title length (p = {cd['title_len']['p']:.2f}) and US seller (p = {cd['is_us']['p']:.2f}) are <b>not</b> significant.</p>"
           f"<p><b>Honest assessment:</b> every model is overall significant (F-test) and each added block improves AIC and passes its nested F-test, so Model D is selected by AIC; but it explains only {best['r2']*100:.1f}% of ln-price variance (test R² {best['test_r2_log']:.3f}). Price is mostly driven by things not in the title (item, size, condition, seller). In USD terms the model is <b>worse</b> than predicting the constant median (MAE ${best['test_mae_usd']:.0f} vs ${m4['baseline_mae_usd']:.0f}; MAPE {best['test_mape_pct']:.0f}% vs {m4['baseline_mape_pct']:.0f}%), because MAE is minimised by the median and MAPE punishes over-prediction of very cheap items. The residuals are heteroscedastic (Breusch–Pagan p {pv(m4['resid']['bp_p'])}), mildly right-skewed (skew {m4['resid']['skew']:.2f}), and not autocorrelated (Durbin–Watson {m4['resid']['dw']:.2f}), so the coefficient p-values should be read as indicative. The label is used as a regressor to describe association, not to claim causation.</p>")
s4 = sec("m4", "brown", "Regression Analysis", "Equation, error terms, fit, significance", [f"LO 4.{i}" for i in range(1, 7)], t41, "04")

# ---------------- Module 5
ms = m5["methods"]; lv = m5["leather"]; sm_ = m5["smote"]; g = m5["gpt_check"]
J = m5["jaccard"]
t51 = task("Task 5.1 — Statistical, distance-based and density-based outlier detection", "Detect unusual listings with several methods and compare them (LO 5.1–5.5, 5.7–5.8).",
           "Features: standardised ln(price), title length, word count. Methods: z-score (|z| &gt; 3), Tukey IQR fences on ln(price), mean distance to 10 nearest neighbours (top 1%), Local Outlier Factor (contamination 1%), and DBSCAN noise points (eps = 0.35, min_samples = 10). Methods are compared by size, Jaccard overlap, and the positive rate among flagged listings.",
           code("M5"),
           tbl(["Method", "Flagged", "% of data", "Positive rate among flagged", "Lift vs base (%.1f%%)" % (m5["base_pos_rate"] * 100)], [[k, v["n"], f"{v['pct']:.2f}", f"{v['pos_rate']*100:.1f}%", f"{v['lift']:.2f}×"] for k, v in ms.items()]) +
           tbl(["Jaccard"] + list(J), [[a] + [f"{J[b][a]:.2f}" for b in J] for a in J]) +
           fig("m5_methods", "Flagged points (orange) for four of the methods in title-length × ln(price) space.") +
           tbl(["Highest-priced listings", "Price (USD)"], [[esc(t["title_clean"]), f"{t['price']:,.0f}"] for t in m5["top_prices"]]),
           f"<p>The methods answer different questions: z-score/IQR look only at price, while kNN/LOF/DBSCAN also look at where a listing sits relative to others in the 3-D feature space, so overlap is partial (see Jaccard matrix). The IQR fence on ln(price) flags {ms['IQR fence (log price)']['pct']:.1f}% of listings and those are {ms['IQR fence (log price)']['lift']:.1f}× more likely than average to be positive; the distance/density flags are <i>not</i> enriched for positives (lift ≈ {ms['LOF (density, 1%)']['lift']:.2f}×), so a generic anomaly score is not a substitute for the classifier. <b>Causes (Content 5.1), as visible in the data:</b> the highest-priced listings are mostly <i>off-topic search hits</i> (cars, replica kits, industrial machinery) that entered the crawl through keyword matching, with one genuine shark-jaw listing among the top six; at the other end, placeholder prices such as $0.01 create low outliers. These causes come from reading the top-6 titles only; other flagged listings were not manually reviewed.</p>")
t52 = task("Task 5.2 — Outlier causes in the larger leather dataset", "Show how data-quality problems create outliers at scale (Content 5.1, LO 5.1).",
           "Profile price in the 152k-row leather listing file: zeros, extreme values, IQR upper fence, currency mix.", "<p class='note'>Implemented in the M5 chunk above.</p>",
           bub([("listings", f"{lv['n']:,}"), ("price = 0", f"{lv['zero']}"), ("price &gt; 100,000", f"{lv['gt_1e5']}"), ("price &gt; 1,000,000", f"{lv['gt_1e6']}")]) +
           fig("m5_leather", "Leather listings: log10(price) histogram and box plot.") +
           tbl(["Largest price", "Currency", "Title"], [[f"{t['price']:,.0f}", t["currency"], esc(t["title"])] for t in lv["top"]]),
           f"<p>The median is ${lv['median']:.0f}, but {lv['iqr_out_pct']:.0f}% of rows exceed the IQR upper fence (${lv['iqr_upper']:,.0f}), which shows a plain IQR rule is too aggressive on this extremely skewed variable. The largest values (up to {lv['max']:,.0f}) belong to inexpensive costume-jewellery/eyewear items, so they are almost certainly <b>data-entry or scraping/unit errors</b>, not real prices; prices are also recorded in several currencies ({', '.join(lv['currencies'])}) without conversion. Any analysis of this file needs currency handling and plausibility filters first.</p>")
rows = [[k, f3(v["cv_f1"]) + " ± " + f3(v["cv_f1_sd"]), f3(v["cv_prec"]), f3(v["cv_rec"]), f3(v["cv_ap"]), f3(v["ho_f1"]), f3(v["ho_ap"]), f"{v['tp']}/{v['fp']}/{v['fn']}/{v['tn']}"] for k, v in sm_.items()]
t53 = task("Task 5.3 — Class imbalance: SMOTE vs class weights vs plain", "Evaluate whether synthetic oversampling helps detect the rare positive class (Content 5.6, LO 5.6; self-learning: F1, AUC-PR, confusion matrix).",
           "Three logistic-regression pipelines on TF-IDF features compared with stratified 5-fold CV and on a held-out 20% split. SMOTE is placed inside the CV pipeline so synthetic points are generated only from training folds. Metrics: precision, recall, F1, average precision (area under the PR curve), confusion matrix (TP/FP/FN/TN).", "<p class='note'>Implemented in the M5 chunk above.</p>",
           tbl(["Model", "CV F1 ± SD", "CV precision", "CV recall", "CV avg. precision", "Hold-out F1", "Hold-out AP", "Hold-out TP/FP/FN/TN"], rows) + fig("m5_smote", "Hold-out precision–recall curves and CV F1 by approach."),
           f"<p>Both imbalance remedies move the model from a <b>high-precision / low-recall</b> operating point ({sm_['Plain LR']['ho_prec']:.2f} / {sm_['Plain LR']['ho_rec']:.2f}) to a <b>high-recall</b> one ({sm_['SMOTE + LR']['ho_rec']:.2f} recall at {sm_['SMOTE + LR']['ho_prec']:.2f} precision), cutting missed positives on the hold-out set from {sm_['Plain LR']['fn']} to {sm_['SMOTE + LR']['fn']} at the cost of about {sm_['SMOTE + LR']['fp']-sm_['Plain LR']['fp']} extra false alarms. In CV, F1 improves by only ≈ {sm_['SMOTE + LR']['cv_f1']-sm_['Plain LR']['cv_f1']:.3f}, about one fold-SD, and <b>SMOTE is indistinguishable from simple class weighting</b> (CV F1 {sm_['SMOTE + LR']['cv_f1']:.3f} vs {sm_['Class-weighted LR']['cv_f1']:.3f}). For triage, where missing a trafficked item is costlier than reviewing a false alarm, the high-recall variants are preferable, and the simpler class-weighted model is sufficient here.</p>")
t54 = task("Task 5.4 — Evaluation metrics on a labelled GPT subset", "Apply confusion-matrix metrics to a second labelled source (self-learning topic).",
           "In leather_validation.csv, 127 of 500 rows carry both a human label and a GPT label. Compare them.", "<p class='note'>Computed in the M5 chunk above.</p>",
           bub([("rows compared", g["n"]), ("accuracy", f3(g["acc"])), ("precision", f3(g["prec"])), ("recall", f3(g["rec"]))]) + tbl(["", "GPT = 1", "GPT = 0"], [["Human = 1", g["tp"], g["fn"]], ["Human = 0", g["fp"], g["tn"]]]),
           f"<p>On this subset GPT agrees with the human label {g['acc']*100:.1f}% of the time (F1 {g['f1']:.3f}) with {g['fn']} missed positives and {g['fp']} false positives. Caveat: only {g['n']} rows are compared (the subset may not be random), so this is indicative, not a general estimate of GPT quality.</p>")
s5 = sec("m5", "orange", "Anomaly Detection", "Outliers, causes, detection methods and SMOTE", [f"LO 5.{i}" for i in range(1, 9)], t51 + t52 + t53 + t54, "05")

# ---------------- Module 6
mm = m6["metrics"]; bestm = min(mm, key=lambda r: r["mae"])
t61 = task("Task 6.1 — Decomposition, stationarity and forecasting", "Apply the time-series toolkit to the only time-dependent signal in the data (LO 6.1–6.6).",
           f"Series: number of listings retrieved per hour in the longest gap-free crawl run ({m6['n']} hours, {m6['start']} → {m6['end']}). Additive decomposition (period 24), ADF stationarity test, then 24-hour-ahead hold-out forecasts (train {m6['n_train']} h, test {m6['n_test']} h) from: overall average, moving average (w = 6), seasonal naive, simple exponential smoothing, linear-trend regression, and ARIMA (p,d,q ≤ (2,1,2) chosen by AIC). Metrics: MAE, RMSE, MAPE, MASE.",
           code("M6"),
           bub([("hours in series", m6["n"]), ("ADF p-value", f3(m6["adf_p"])), ("seasonal strength", f3(m6["season_strength"])), ("ARIMA order", str(tuple(m6["arima_order"])))]) + fig("m6_decomp", "Additive decomposition: observed, trend, 24-hour seasonal component, residual.") +
           tbl(["Method", "MAE", "RMSE", "MAPE (%)", "MASE"], [[r["method"], f"{r['mae']:.1f}", f"{r['rmse']:.1f}", f"{r['mape']:.1f}", f"{r['mase']:.2f}"] for r in mm]) + fig("m6_forecast", "24-hour hold-out forecasts vs actual."),
           f"<p>The ADF test does not reject a unit root (p = {m6['adf_p']:.2f}), so the series is treated as non-stationary and ARIMA chose d = 1. The 24-hour seasonal component is modest (strength {m6['season_strength']:.2f}). <b>No method forecasts well</b>: the lowest MAE is {bestm['mae']:.1f} listings/hour for “{bestm['method']}” against a series mean of {m6['mean']:.0f}, and all methods are within a few listings of each other, so the differences are not meaningful. MASE is above 6 for every method because it is scaled by the one-step naive error while these are 24-step forecasts, so it should be read as a relative scale, not a pass/fail. ARIMA (order chosen by AIC among the candidate orders) is not the best method on the hold-out.</p>"
           "<p><b>Important limitation:</b> this series measures how many listings the <i>crawler</i> retrieved per hour, not marketplace activity. The data spans only ~10 days with gaps, the usable gap-free run is 94 hours (about four daily cycles), and the hold-out is a single 24-hour window. The results demonstrate the methods and metrics on real data, but they should not be used to draw conclusions about wildlife-trade trends.</p>")
s6 = sec("m6", "olive", "Time Series Forecasting", "Decomposition, smoothing, regression, ARIMA, error measures", [f"LO 6.{i}" for i in range(1, 7)], t61, "06")

# ---------------- Coverage + limitations
